--
-- Table structure for table `예측용_열차예매_더미`
--

DROP TABLE IF EXISTS `예측용_열차예매_더미`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `예측용_열차예매_더미` (
  `열차운행ID` bigint NOT NULL COMMENT '엑셀 원본 열차운행ID',
  `날짜` date NOT NULL,
  `열차번호` varchar(30) NOT NULL,
  `열차종류` varchar(30) NOT NULL,
  `운행구분` varchar(10) NOT NULL,
  `예정시각` time NOT NULL,
  `승강장번호` int NOT NULL,
  `예매율` decimal(5,4) NOT NULL COMMENT '0~1 비율. 0.80은 80%',
  `데이터구분` varchar(30) NOT NULL DEFAULT '예측용_더미',
  PRIMARY KEY (`열차운행ID`),
  UNIQUE KEY `uq_열차운행구간` (`날짜`,`열차번호`,`운행구분`,`예정시각`),
  KEY `idx_날짜_운행구분_예정시각` (`날짜`,`운행구분`,`예정시각`),
  KEY `idx_승강장_날짜` (`승강장번호`,`날짜`),
  CONSTRAINT `chk_예측열차더미_승강장번호` CHECK ((`승강장번호` > 0)),
  CONSTRAINT `chk_예측열차더미_예매율` CHECK ((`예매율` between 0 and 1)),
  CONSTRAINT `chk_예측열차더미_운행구분` CHECK ((`운행구분` in (_utf8mb4'도착',_utf8mb4'출발')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

